<script>
document.addEventListener('DOMContentLoaded', function() {
    const themeAutoBtn = document.getElementById('btn-auto');
    const themeLightBtn = document.getElementById('btn-light');
    const themeDarkBtn = document.getElementById('btn-dark');

    function getUTC8Hour() {
        const d = new Date();
        const utc = d.getTime() + (d.getTimezoneOffset() * 60000);
        const utc8 = new Date(utc + (3600000 * 8));
        return utc8.getHours();
    }

    function isNightTimeInUTC8() {
        const hour = getUTC8Hour();
        return hour >= 18 || hour < 6;
    }

    function setTheme(theme) {
        if (theme === 'auto') {
            const isNight = isNightTimeInUTC8();
            document.documentElement.setAttribute('data-theme', isNight ? 'dark' : 'light');
        } else {
            document.documentElement.setAttribute('data-theme', theme);
        }

        localStorage.setItem('xiangyata-theme', theme);
        [themeAutoBtn, themeLightBtn, themeDarkBtn].forEach(btn => btn.classList.remove('active'));
        if (theme === 'auto') themeAutoBtn.classList.add('active');
        if (theme === 'light') themeLightBtn.classList.add('active');
        if (theme === 'dark') themeDarkBtn.classList.add('active');
    }

    setInterval(() => {
        if (localStorage.getItem('xiangyata-theme') === 'auto') {
            const currentTheme = document.documentElement.getAttribute('data-theme');
            const targetTheme = isNightTimeInUTC8() ? 'dark' : 'light';
            if (currentTheme !== targetTheme) {
                document.documentElement.setAttribute('data-theme', targetTheme);
            }
        }
    }, 60000);

    themeAutoBtn.addEventListener('click', () => setTheme('auto'));
    themeLightBtn.addEventListener('click', () => setTheme('light'));
    themeDarkBtn.addEventListener('click', () => setTheme('dark'));

    const savedTheme = localStorage.getItem('xiangyata-theme') || 'auto';
    setTheme(savedTheme);

    // --- Setup ---
    const animatedContent = document.getElementById('animated-content');
    const now = new Date();
    document.getElementById('current-time').textContent = `编辑于 今天 ${now.getHours()}:${String(now.getMinutes()).padStart(2, '0')}`;
    const highlightColors = ['#FF3B30', '#FF9500', '#007AFF', '#5856D6', '#5AC8FA', '#FF2D55'];

    // --- Inline Parsing Functions ---
    const applyCode = (t) => t.replace(/`(.*?)`/g, (m, c) => `<code>${c}</code>`);
    const applyBold = (t) => t.replace(/\*\*(.*?)\*\*/g, (m, c) => `<strong>${c}</strong>`);
    const applyStrikethrough = (t) => t.replace(/\~\~(.*?)\~\~|<del>(.*?)<\/del>/g, (m, c1, c2) => `<s>${c1 || c2}</s>`);
    const applyItalic = (t) => t.replace(/\*(.*?)\*/g, (m, c) => `<em>${c}</em>`);
    const applyHighlight = (t) => t.replace(/(\[.*?\]|\(.*?\)|".*?"|“.*?”)/g, (m) => {
        const randomColor = highlightColors[Math.floor(Math.random() * highlightColors.length)];
        return `<span class="highlight" style="color: ${randomColor};">${m}</span>`;
    });

    function parseInlineMarkdown(text) {
        return applyHighlight(applyItalic(applyStrikethrough(applyBold(applyCode(text)))));
    }

    // --- Main Recursive Parser ---
    function parseContent(lines) {
        const htmlChunks = [];
        let i = 0;

        const isTableSeparator = (line) => /^\|(?:\s*:?-+:?\s*\|)+$/.test(line);

        while (i < lines.length) {
            const trimmedLine = lines[i].trim();

            if (i + 1 < lines.length && isTableSeparator(lines[i + 1].trim())) {
                const tableData = { headers: [], alignments: [], rows: [] };
                tableData.alignments = lines[i + 1].trim().split('|').slice(1, -1).map(s => {
                    const align = s.trim();
                    if (align.startsWith(':') && align.endsWith(':')) return 'center';
                    if (align.endsWith(':')) return 'right';
                    return 'left';
                });
                tableData.headers = lines[i].trim().split('|').slice(1, -1).map(s => s.trim());
                let rowIndex = i + 2;
                while (rowIndex < lines.length && lines[rowIndex].trim().startsWith('|')) {
                    tableData.rows.push(lines[rowIndex].trim().split('|').slice(1, -1).map(s => s.trim()));
                    rowIndex++;
                }
                let tableHTML = '<table><thead><tr>';
                tableData.headers.forEach((h, idx) => { tableHTML += `<th style="text-align: ${tableData.alignments[idx]};">${parseInlineMarkdown(h)}</th>`; });
                tableHTML += '</tr></thead><tbody>';
                tableData.rows.forEach(r => {
                    tableHTML += '<tr>';
                    r.forEach((c, idx) => { tableHTML += `<td style="text-align: ${tableData.alignments[idx]};">${parseInlineMarkdown(c)}</td>`; });
                    tableHTML += '</tr>';
                });
                tableHTML += '</tbody></table>';
                htmlChunks.push(tableHTML);
                i = rowIndex;

            } else if (trimmedLine.startsWith('>')) {
                const quoteGroup = [];
                let currentIndex = i;
                while (currentIndex < lines.length && lines[currentIndex].trim().startsWith('>')) {
                    quoteGroup.push(lines[currentIndex].trim());
                    currentIndex++;
                }

                const nestedLines = quoteGroup.map(line => line.substring(line.indexOf('>') + 1));
                const innerHtml = parseContent(nestedLines).join('');

                htmlChunks.push(`<div class="quote-center">${innerHtml}</div>`);
                i = currentIndex;

            } else if (trimmedLine.startsWith('||')) {
                const groupedRawInnerLines = [];
                let currentIndex = i;
                while (currentIndex < lines.length && lines[currentIndex].trim().startsWith('||')) {
                    const currentBlockLine = lines[currentIndex].trim();
                    let rawInnerLine = currentBlockLine.substring(2);
                    let cleanedInnerLine = rawInnerLine.replace(/\|\|/g, '');
                    groupedRawInnerLines.push(cleanedInnerLine);
                    currentIndex++;
                }
                const parsedInnerHtml = parseContent(groupedRawInnerLines).join('');
                htmlChunks.push(`<div class="highlight-block">${parsedInnerHtml}</div>`);
                i = currentIndex;

            } else if (trimmedLine.startsWith('* ')) {
